// A plataforma envia somente preferências/áreas. Achados completos e IDs de correção ficam no computador.
using System.Text.Json;
using Arcoll.WinUI3.Services.PenteFino;
namespace Arcoll.WinUI3.Services;
internal static class GeneralRemoteCommands
{
 private static readonly SemaphoreSlim Gate=new(1,1);
 private static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true};
 private sealed record State(string ReportId,AnalysisPreferences Preferences,string PathsHash,bool Historical);
 public static async Task<string> RunAsync(JsonElement request,PlatformClient platform,long commandId,CancellationToken cancellation){
  await Gate.WaitAsync(cancellation);using var operation=CancellationTokenSource.CreateLinkedTokenSource(cancellation);using var watch=CancellationTokenSource.CreateLinkedTokenSource(cancellation);object? latest=null;
  var monitor=Task.Run(async()=>{try{while(true){await Task.Delay(1500,watch.Token);var status=await platform.PostAsync("gestor-general-status",platform.WithCredentials(("command_id",commandId)),watch.Token,10);if(status.GetProperty("status").GetString()!="running"){operation.Cancel();return;}var value=Volatile.Read(ref latest);if(value is not null)await platform.AckAsync(commandId,"running",JsonSerializer.Serialize(value,Json),watch.Token);}}catch(OperationCanceledException){}catch(Exception error){RuntimeLog.Write("Acompanhamento da Análise geral: "+error.Message);operation.Cancel();}},CancellationToken.None);
  try{
   var scope=ResultsStore.Hash(platform.Config.Origin+"|"+platform.Config.SiteCode+"|"+platform.Config.Fingerprint)[..24];var store=new ResultsStore(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TI-Digital","PenteFino","remote",scope));
   var path=store.LocalPath("remote-state.json");State? state=File.Exists(path)?JsonSerializer.Deserialize<State>(await File.ReadAllTextAsync(path,operation.Token),Json):null;
   var settings=await platform.PostAsync("gestor-clean-local-settings",platform.WithCredentials(),operation.Token,20);var paths=settings.GetProperty("settings");string[] Read(string key)=>paths.TryGetProperty(key,out var p)&&p.ValueKind==JsonValueKind.Array?p.EnumerateArray().Select(x=>x.GetString()??"").ToArray():[];var exclusions=Read("exclusions");var folders=Read("custom_folders");var pathsHash=ResultsStore.Hash(JsonSerializer.Serialize(new{exclusions,folders},Json));
   var action=request.GetProperty("action").GetString();var requestId=request.GetProperty("requestId").GetString()??"";ScanReport report;object? outcome=null;string notice;AnalysisPreferences preferences;
   if(action=="scan"){
    preferences=GeneralAnalysisEngine.Validate(request.GetProperty("preferences").Deserialize<AnalysisPreferences>(Json)??throw new InvalidDataException("Configurações ausentes."),CleanEngine.Catalog());
    state=new("",preferences,pathsHash,true);ResultsStore.Atomic(path,JsonSerializer.Serialize(state,Json));store.SaveSettings(new("detailed",GeneralAnalysisEngine.Modules(preferences),exclusions,[],[],preferences,folders));
    var progress=new Progress<ProgressState>(p=>Volatile.Write(ref latest,new{type="progress",requestId,state=p}));var options=new ScanOptions("detailed",GeneralAnalysisEngine.Modules(preferences),exclusions,[]);var policy=new PathPolicy(PathPolicy.WindowsRules("detailed"),exclusions);
    report=await new ScanOrchestrator(store,new GeneralAnalysisEngine(platform.Config,preferences,exclusions,folders).Checkers()).ScanAsync(options,policy,progress,operation.Token);state=state with{ReportId=report.Id,Historical=report.Cancelled};ResultsStore.Atomic(path,JsonSerializer.Serialize(state,Json));notice=report.Cancelled?"Análise interrompida.":"Análise concluída. Revise as áreas antes de corrigir.";
   }else if(action=="fix"){
    if(state is null||state.Historical||state.PathsHash!=pathsHash||paths.TryGetProperty("general_preferences",out var currentPreferences)&&JsonSerializer.Serialize(GeneralAnalysisEngine.Validate(currentPreferences.Deserialize<AnalysisPreferences>(Json)??throw new InvalidDataException("Configurações inválidas."),CleanEngine.Catalog()),Json)!=JsonSerializer.Serialize(state.Preferences,Json))throw new InvalidOperationException("Faça nova análise: configurações ou resultado mudaram.");report=store.Last()??throw new InvalidOperationException("Nenhuma análise disponível.");if(report.Id!=state.ReportId)throw new InvalidOperationException("Resultado da análise mudou.");preferences=state.Preferences;
    var modules=request.GetProperty("modules").EnumerateArray().Select(x=>x.GetString()??"").ToArray();var ids=Presentation.CorrectionIds(report,request.GetProperty("reportId").GetString()??"",modules);var byId=report.Modules.SelectMany(m=>m.Items).ToDictionary(i=>i.Id);var moduleById=report.Modules.SelectMany(m=>m.Items.Select(i=>(i.Id,m.Id))).ToDictionary(p=>p.Item1,p=>p.Item2);
    state=state with{Historical=true};ResultsStore.Atomic(path,JsonSerializer.Serialize(state,Json));var progress=new Progress<FixProgressState>(p=>Volatile.Write(ref latest,new{type="fix-progress",requestId,state=new{p.Completed,p.Total,p.State,p.Succeeded,p.Failed,module=p.Id is null?null:moduleById.GetValueOrDefault(p.Id)}}));
    var fix=await new FixEngine(store,new PathPolicy(PathPolicy.WindowsRules("detailed"),exclusions),new GeneralAnalysisEngine(platform.Config,preferences,exclusions,folders).FixAsync).FixAsync(report,ids,operation.Token,progress,request.TryGetProperty("createRestorePoint",out var restore)&&restore.ValueKind==JsonValueKind.True);
    outcome=new{kind="fix",session=fix.Session,applied=fix.Results.Where(r=>r.Ok).Sum(r=>Math.Max(1,byId[r.Id].Quantity)),failed=fix.Results.Where(r=>!r.Ok).Sum(r=>Math.Max(1,byId[r.Id].Quantity)),pending=Math.Max(0,ids.Sum(id=>Math.Max(1,byId[id].Quantity))-fix.Results.Sum(r=>Math.Max(1,byId[r.Id].Quantity))),cancelled=fix.Cancelled,countsPartial=fix.CountsPartial,errors=fix.Results.Where(r=>!r.Ok).Select(r=>r.Message).Distinct().Take(8).ToArray()};notice=fix.Cancelled?"Correção interrompida; confira as etapas confirmadas.":"Correção concluída. Faça nova análise para atualizar o diagnóstico.";
   }else throw new InvalidDataException("Operação de análise inválida.");
   watch.Cancel();await monitor;var wire=JsonSerializer.SerializeToElement(new{tool="general",requestId,report=Presentation.Summarize(report),preferences,historical=state.Historical,notice,outcome},Json);await platform.PostAsync("gestor-clean-result",platform.WithCredentials(("command_id",commandId),("report",wire)),operation.Token,40);return notice;
  }finally{watch.Cancel();try{await monitor;}finally{Gate.Release();}}
 }
}
